use crate::navigation::{destination::NearDestination,flight::FlyRoute,glide::airway_search::{AirwaySearch,body_box},replanner::SearchGoal,search::{Failure,Limits,Outcome,SearchProblem},staged_search::SearchDestination};
type Goal=SearchDestination<Box<dyn Fn(BlockPos)->bool>>;
type AirSearch=AirwaySearch<S,World,Goal>;
fn outcome(o:Outcome<FlyRoute>)->String{match o{Outcome::Searching=>"S".into(),Outcome::AlreadyThere=>"A".into(),Outcome::Failed(f)=>format!("E:{}",match f{Failure::InvalidDestination=>"INVALID_DESTINATION",Failure::TooFar=>"TOO_FAR",Failure::NoPath=>"NO_PATH",Failure::TooComplex=>"TOO_COMPLEX",Failure::TimedOut=>"TIMED_OUT"}),Outcome::Found(r)=>format!("F:{}:{}:{}:{}",vector(r.start),r.points.iter().copied().map(vector).collect::<Vec<_>>().join(";"),r.can_reach,vector(r.end()))}}
fn extra(a:&[&str],t:&mut Terrain<S,World>,search:&mut Option<AirSearch>,expected:&str)->String {match a[0]{
 "air"=>{let start=v(a[1]);let level=t.level().clone();let range=(a[5]!="-").then(||d(a[5]));let descriptor=SearchGoal{goal:NearDestination::new(v(a[2]),d(a[3])),start,stage_range:range};let destination=SearchDestination::new(descriptor,Box::new(move|p|level.is_known(p)&&level.is_inside_border(f64::from(p.x)+0.5,f64::from(p.z)+0.5))as Box<dyn Fn(BlockPos)->bool>);let mut limits=Limits::new(d(a[6]));limits.max_visited_nodes=a[7].parse().unwrap();limits.visited_nodes_per_slice=a[8].parse().unwrap();limits.max_compute_nanos=a[9].parse().unwrap();*search=Some(AirwaySearch::new(Terrain::new(t.level().clone(),t.width(),t.height(),t.can_open_doors()),start,destination,d(a[4]),range.is_some(),limits));"-".into()},
 "node"=>{let q=p(a[1]);let s=&mut search.as_mut().unwrap().problem;let edges=s.neighbors(&q);format!("{}|{}|{}",s.is_goal(&q),s.heuristic(&q).to_bits(),edges.into_iter().map(|e|format!("{}:{}",position(e.node),e.cost.to_bits())).collect::<Vec<_>>().join(";"))},
 "open"=>{let q=p(a[1]);let s=&mut search.as_mut().unwrap().problem;format!("{},{}",s.is_open(q.x,q.y,q.z),s.is_roomy(q.x,q.y,q.z))},
 "line"=>search.as_mut().unwrap().problem.is_clear_line(v(a[1]),v(a[2]),d(a[3])).to_string(),"glideBox"=>bbox(body_box(v(a[1]),d(a[2]))),
 "advance"=>{let s=search.as_mut().unwrap();let nanos=expected.split('~').nth(1).unwrap().parse::<i64>().unwrap();let elapsed=nanos.wrapping_sub(s.engine.compute_nanos());let mut times=[0,elapsed].into_iter();let returned=s.advance_with_clock(||times.next().unwrap()).map_or_else(|_|"invalid".into(),outcome);let iterations=s.engine.search.as_ref().map_or_else(||"-".into(),|s|s.iterations.to_string());let finished=s.engine.search.as_ref().map_or_else(||"-".into(),|s|s.is_finished().to_string());format!("{returned}~{}~{iterations}~{finished}~{}",s.engine.compute_nanos(),s.preview().map_or_else(||"-".into(),|p|p.into_iter().map(vector).collect::<Vec<_>>().join(";")))},
 "preview"=>search.as_mut().unwrap().preview().map_or_else(||"-".into(),|p|p.into_iter().map(vector).collect::<Vec<_>>().join(";")),_=>panic!("{a:?}")}}
